def main():
    branch = subprocess.run(
        ["git", "branch", "--show-current"], cwd=ROOT, text=True,
        capture_output=True, check=True
    ).stdout.strip()
    if branch != BRANCH:
        raise SystemExit(f"ERROR: expected branch {BRANCH}, current={branch}")
    for rel, content in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        desired = content.rstrip() + "\n"
        if path.exists() and path.read_text(encoding="utf-8") == desired:
            print(f"PASS: {rel} already synchronized")
        else:
            path.write_text(desired, encoding="utf-8")
            print(f"PASS: synchronized {rel}")
    print("PASS: Patch 004 apply complete")

if __name__ == "__main__":
    main()
